/**
 * IAU constellation abbreviations to full names.
 *
 * The bundled `constellations.json` (d3-celestial, BSD-3) carries the
 * three-letter abbreviation and the line geometry, and nothing else. The
 * immersive view names the constellation you are looking at, and "CVn" is not
 * a name anybody reads.
 *
 * These are IAU designations, which are facts rather than anybody's data set,
 * so they live here as a constant instead of being regenerated by
 * scripts/build-sky-data.mjs.
 *
 * Only the 25 the view draws are listed (scripts/build-sky-data.mjs, DRAWN).
 * A figure added there needs its name added here, and a test checks it.
 */
export const CONSTELLATION_NAMES: Record<string, string> = {
  Ari: "Aries", Tau: "Taurus", Gem: "Gemini", Cnc: "Cancer",
  Leo: "Leo", Vir: "Virgo", Lib: "Libra", Sco: "Scorpius",
  Sgr: "Sagittarius", Cap: "Capricornus", Aqr: "Aquarius", Psc: "Pisces",
  Ori: "Orion", UMa: "Ursa Major", UMi: "Ursa Minor", Cas: "Cassiopeia",
  Cyg: "Cygnus", Lyr: "Lyra", Aql: "Aquila", And: "Andromeda",
  Per: "Perseus", Peg: "Pegasus", CMa: "Canis Major", Cru: "Crux",
  Boo: "Boötes",
};
